const items = [];

for (const item of $input.all()) {
  const card = item.json;

  let desc = {};
  try {
    // Remove escapes do Trello e faz parse
    const descClean = card.desc
      .replace(/\\_/g, '_')
      .replace(/\\"/g, '"');
    desc = JSON.parse(descClean);
  } catch (e) {
    desc = {
      content_type: '',
      idea_description: '',
      caption: '',
      image_url: '',
      scheduled_time: '',
      expected_generation_date: '',
      ig_post_id: '',
      error_message: 'Erro ao parsear JSON da descrição: ' + e.message,
      parse_error: 'Erro ao parsear JSON da descrição: ' + e.message
    };
  }

  items.push({
    json: {
      card_id: card.id,
      card_name: card.name,
      card_url: card.url,
      content_type: desc.content_type || '',
      idea_description: desc.idea_description || '',
      caption: desc.caption || '',
      image_url: desc.image_url || '',
      scheduled_time: desc.scheduled_time || '',
      expected_generation_date: desc.expected_generation_date || '',
      ig_post_id: desc.ig_post_id || '',
      error_message: desc.error_message || '',
      parse_error: desc.parse_error || '',
      card_raw_desc: card.desc
    }
  });
}

return items;

const items = [];

// Brasília = UTC-3
const now = new Date();
const brasilNow = new Date(now.getTime() - (3 * 60 * 60 * 1000));
const today = brasilNow.toISOString().split('T')[0];

for (const item of $input.all()) {
  const cardDate = item.json.expected_generation_date.split('T')[0];

  if (cardDate === today) {
    items.push(item);
  }
}

return items;

// Mapeamento content_type -> template/tag, conforme a página "Renderização de
// Imagem — Templates & Lambda" no Notion. Os 4 templates de headline entram
// num pool de rotação aleatória; quote e tag_stat são fixos por content_type.
const TEMPLATE_MAP = {
  hook:          { pool: true,  template: null,      tag: 'PERGUNTA' },
  pain_mirror:   { pool: false, template: 'quote',    tag: null },
  myth:          { pool: true,  template: null,       tag: 'MITO' },
  trust:         { pool: true,  template: null,       tag: 'CONFIANÇA' },
  hook_stat:     { pool: false, template: 'tag_stat', tag: 'DADO' },
  news_reaction: { pool: true,  template: null,       tag: 'NOTÍCIA' },
  math_example:  { pool: false, template: 'tag_stat', tag: 'CONTA' },
  how_it_works:  { pool: true,  template: null,       tag: 'GUIA' },
  glossario:     { pool: true,  template: null,       tag: 'GUIA' },
  cta:           { pool: true,  template: null,       tag: 'ACESSO' }
};

const POOL_TEMPLATES = ['hook_simples', 'framed', 'left_editorial', 'tag_headline'];

// content_type que exige dado/fonte real verificável na idea_description —
// nunca inventar número ou notícia (checado de fato depois da resposta do
// Claude, no node "Parse Claude Response").
const REQUIRES_SOURCE = ['hook_stat', 'math_example', 'news_reaction'];

const items = [];

for (const item of $input.all()) {
  const card = item.json;
  const contentType = (card.content_type || 'hook').trim();
  const config = TEMPLATE_MAP[contentType];
  const safeConfig = config || TEMPLATE_MAP.hook;

  const template = safeConfig.pool
    ? POOL_TEMPLATES[Math.floor(Math.random() * POOL_TEMPLATES.length)]
    : safeConfig.template;

  const fieldSchema = template === 'quote' ? 'quote'
    : template === 'tag_stat' ? 'stat'
    : 'headline';

  items.push({
    json: {
      ...card,
      content_type: contentType,
      template,
      fixed_tag: safeConfig.tag,
      field_schema: fieldSchema,
      requires_source: REQUIRES_SOURCE.includes(contentType),
      // Começa limpo a cada execução: um card que falhou antes e voltou pra
      // ✍️ Para Gerar precisa ser reprocessado, não re-rejeitado pelo erro velho.
      generation_error: card.parse_error || (config ? '' : `content_type desconhecido: "${contentType}"`)
    }
  });
}

return items;

// Builds the Claude prompt dynamically based on the output schema required by
// the randomly-picked template (headline / quote / stat).
//
// EDIT ME: BRAND_SYSTEM below is a placeholder — replace it with your own
// brand voice, product description, and constraints. CONTENT_TYPE_RULES is a
// working example content taxonomy (10 content pillars); adapt the wording
// to your niche, or trim/extend the list. The mechanics (schema selection,
// the missing_source_data guardrail) are reusable as-is.
const BRAND_SYSTEM = `You are the content-creation agent for [YOUR BRAND] — [one sentence describing what the product/brand is and what makes it different].

## About the product
Positioning: "[your one-line positioning statement]"
Audience: [who you're talking to and what problem they have]
Value proposition: [what makes this trustworthy or different from alternatives]

## Tone of voice
- [bullet describing tone]
- [bullet describing tone]
- [bullet describing tone]

## What to NEVER do
- Don't recommend specific products/services (if that's a real constraint for your brand)
- Don't use a salesy tone or artificial urgency
- Don't use more than 2 emojis per post
- Don't make promises about outcomes or results
- Don't invent data, statistics, or facts that aren't explicitly present in the idea description

## Account context
Instagram: @[your_handle]
Current phase: [growth stage / current goal]
Content goal: [what you want this content to achieve]`;

const SCHEMA_INSTRUCTIONS = {
  headline: `{
  "headline": "main hook, 12 words max",
  "subtext": "complements the headline, optional — use an empty string if not needed",
  "caption": "full caption for the Instagram post"
}`,
  quote: `{
  "quote": "the pain/recognition line, first person, as if it were someone speaking",
  "attribution": "short attribution — empty string if there's no specific person",
  "caption": "full caption for the Instagram post"
}`,
  stat: `{
  "big_number": "the data point itself, e.g. '13.65%' or '$3,200' — must come literally from the idea description, never invented",
  "label": "short explanation of what the number means",
  "caption": "full caption for the Instagram post"
}`
};

// EDIT ME: rename/reword/trim these 10 content pillars to match your niche.
// The three flagged requiresSource in "Determine Template & Schema" (hook_stat,
// math_example, news_reaction) are the ones this prompt will refuse to
// fabricate data for — keep that behavior even if you rename the pillars.
const CONTENT_TYPE_RULES = {
  hook: 'Direct hook — an attention-grabbing line that stops the scroll.',
  myth: 'Debunk a common misconception in your niche, without sounding condescending.',
  trust: 'Reinforce your neutrality/trust positioning — no personalized recommendations.',
  hook_stat: 'Credibility stat from a real source. USE ONLY the number/source provided in the idea description. If the description does not contain a concrete, verifiable data point, do not invent one — this will be treated as an error.',
  news_reaction: 'Reacting to real news. USE ONLY the facts provided in the idea description. If the description does not contain a real, concrete news item, do not invent one — this will be treated as an error.',
  math_example: 'Worked numerical example. The numbers must come from the idea description, never invented.',
  how_it_works: 'Explain how the product works, without a sales tone.',
  glossario: 'Explain a term from your field in plain language.',
  cta: 'Invite the audience to take your call to action, without artificial urgency.',
  pain_mirror: 'Mirror a common frustration your audience has felt, in first person, without irony.'
};

const items = [];

for (const item of $input.all()) {
  const card = item.json;

  const schema = SCHEMA_INSTRUCTIONS[card.field_schema] || SCHEMA_INSTRUCTIONS.headline;
  const rule = CONTENT_TYPE_RULES[card.content_type] || '';

  const userPrompt = `Create the content for an Instagram post based on this idea:

Title: ${card.card_name}
Content type: ${card.content_type}
Description: ${card.idea_description}

Specific guidance for this content type: ${rule}
${card.requires_source ? '\nATTENTION: this content type requires a real data point/source. If the description above does not contain a concrete, verifiable number, statistic, or fact, respond with only {"error": "missing_source_data"} — do not invent one to fill the gap.' : ''}

Return ONLY the raw JSON below, no markdown, no \`\`\`json, no backticks, no text before or after:

${schema}

IMPORTANT: in any text field, replace double quotes with single quotes. Example: use 'did my money grow?' instead of "did my money grow?".`;

  items.push({
    json: {
      ...card,
      system_prompt: BRAND_SYSTEM,
      user_prompt: userPrompt
    }
  });
}

return items;

// O node Anthropic substitui item.json inteiro pela resposta bruta da API —
// tudo que veio antes (card_id, template, content_type, etc.) some. Por isso
// recuperamos esses campos direto do node anterior por nome, em vez de
// espalhar (...) o item atual.
const claudeItems = $input.all();
const upstreamItems = $('Build Claude Prompt').all();

const items = [];

for (let i = 0; i < claudeItems.length; i++) {
  const claude = claudeItems[i].json;
  const card = upstreamItems[i].json;

  // content_type desconhecido, já sinalizado antes de chamar o Claude —
  // propaga o erro sem tentar interpretar a resposta do modelo.
  if (card.generation_error) {
    items.push({ json: card });
    continue;
  }

  const raw = claude.content[0].text;

  let parsed;
  try {
    parsed = JSON.parse(raw);
  } catch (e) {
    parsed = { error: 'invalid_json_from_model' };
  }

  if (parsed.error) {
    items.push({
      json: {
        ...card,
        generation_error: parsed.error === 'missing_source_data'
          ? 'Claude recusou gerar: descrição da ideia não trouxe dado/fonte real verificável.'
          : `Erro ao interpretar resposta do modelo: ${parsed.error}`
      }
    });
    continue;
  }

  items.push({
    json: {
      ...card,
      headline: parsed.headline || '',
      subtext: parsed.subtext || '',
      quote: parsed.quote || '',
      attribution: parsed.attribution || '',
      big_number: parsed.big_number || '',
      label: parsed.label || '',
      caption: parsed.caption || card.caption || ''
    }
  });
}

return items;

const items = [];

for (const item of $input.all()) {
  const card = item.json;
  let fields = {};

  if (card.field_schema === 'quote') {
    fields = { quote: card.quote, attribution: card.attribution };
  } else if (card.field_schema === 'stat') {
    fields = { tag: card.fixed_tag, big_number: card.big_number, label: card.label };
  } else {
    fields = { headline: card.headline };
    if (card.fixed_tag) fields.tag = card.fixed_tag;
    if (card.subtext) fields.subtext = card.subtext;
  }

  items.push({ json: { ...card, lambda_fields: fields } });
}

return items;

// O node HTTP Request também substitui item.json pela resposta (statusCode/
// headers/body) — mesmo problema do node do Claude. Recupera os dados de
// antes (card_id, template, caption, etc.) direto do node anterior.
const responseItems = $input.all();
const upstreamItems = $('Build Lambda Fields').all();

const items = [];

for (let i = 0; i < responseItems.length; i++) {
  const response = responseItems[i].json;
  const card = upstreamItems[i].json;
  const status = response.statusCode;
  const body = response.body || {};

  if (status === 200 && body.image_url) {
    items.push({ json: { ...card, image_url: body.image_url } });
  } else {
    items.push({
      json: {
        ...card,
        generation_error: `Lambda retornou ${status}: ${body.error || 'erro desconhecido'}`
      }
    });
  }
}

return items;
